/**
 * One scenario per check of two-records-build-standard, for Draw Match.
 *
 * Generated by `npx @aipathway/conformance init two-records-build-standard`, from
 * https://aipathway.com.au/explore-ai/two-records-build-standard, then filled in.
 *
 * The pair in every scenario: a small landlord's own books (source a, the
 * deposits from the agency on the bank feed, coded into rent, fees and net)
 * against the agency's owner statement register (source b, one line per
 * disbursement). The shared key is the payment_id the agency's trust ledger
 * issues for each disbursement and prints in the EFT reference. Amounts are
 * Australian dollars.
 *
 * Every holds() reads the world and returns a strict true or false.
 */

import { TwoRecordsWorld } from "@aipathway/conformance";

const HOUR = 60 * 60 * 1000;
const OWNER = "Priya Nair (owner's bookkeeper)";
const ACCEPTOR = "Priya Nair";

/** The written pair contract a person signed off, dated. */
const contract = (over = {}) => ({
  id: "PC-draw-match-2026-10-01",
  sourceA: "owner's books: agency deposits on the bank feed, coded rent / fees / net, by payment_id in the EFT reference",
  sourceB: "agency owner statement register: trust account disbursement lines, by payment_id",
  key: "payment_id",
  // The bank is right about what landed; the agency statement is right about
  // rent collected and fees charged.
  masterByField: { net: "a", rent: "b", fees: "b" },
  // Two cents of rounding on the net, written by a person. Nothing else.
  toleranceByField: { net: 0.02 },
  threshold: { amount: 500, mismatchRate: 0.5 },
  schedule: "daily 07:00 Australia/Brisbane",
  owner: OWNER,
  ...over,
});

/** One disbursement as a record. The label is an address, never a key. */
const rec = (key, name, rent, fees, net = +(rent - fees).toFixed(2)) => ({ key, name, fields: { rent, fees, net } });

const pairOf = (...rows) => ({ sourceA: rows.map((r) => ({ ...r, fields: { ...r.fields } })), sourceB: rows.map((r) => ({ ...r, fields: { ...r.fields } })) });

const calls = (world, port) => world.calls.filter((c) => c.port === port);
const writes = (world) => calls(world, "write_ledger");
const isCount = (n) => Number.isInteger(n) && n >= 0;
const sameMasters = (x, y) => {
  const kx = Object.keys(x ?? {}).sort();
  const ky = Object.keys(y ?? {}).sort();
  return kx.length === ky.length && kx.every((k, i) => k === ky[i] && x[k] === y[k]);
};

export const scenarios = [
  {
    checkId: "a-pair-is-declared-not-guessed",
    // 1. The contract is read before either source; the published run names it
    //    and declares the same master per field.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        ...pairOf(rec("PAY-24011", "4/18 Banksia St, Mackay", 2600, 213.2), rec("PAY-24012", "7 Wattle Ct, Mackay", 2210, 181.22)),
      }),
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const c = contract();
      const iContract = world.firstCall("read_ledger", (x) => x.request?.contract === true);
      const iA = world.firstCall("read_job", (x) => x.request?.source === "a");
      const iB = world.firstCall("read_ledger", (x) => x.request?.source === "b");
      return (
        iContract >= 0 &&
        iA > iContract &&
        iB > iContract &&
        world.runs.length === 1 &&
        world.runs.every((r) => r.contractId === c.id && r.joinedOn === c.key && sameMasters(r.masterByField, c.masterByField))
      );
    },
    describe: (world) => `runs ${JSON.stringify(world.runs.map((r) => ({ contractId: r.contractId, joinedOn: r.joinedOn, masters: r.masterByField })))}`,
  },
  {
    checkId: "keys-join-ids-not-labels",
    // 2. Same address and same amounts, different payment ids: not a pair.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-31001", "12 Cassia Ave, Townsville", 2400, 211.2), rec("PAY-31003", "3 Fig Tree Rd, Townsville", 1980, 174.24)],
        sourceB: [rec("PAY-31002", "12 Cassia Ave, Townsville", 2400, 211.2), rec("PAY-31003", "3 Fig Tree Rd, Townsville", 1980, 174.24)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const run = world.runs[0];
      const lookalikes = new Set(["PAY-31001", "PAY-31002"]);
      return (
        world.runs.length === 1 &&
        run.joinedOn === "payment_id" &&
        run.matched === 1 &&
        world.differences.every((d) => !lookalikes.has(d.key)) &&
        world.differences.length === 0 &&
        world.corrections.length === 0 &&
        writes(world).length === 0
      );
    },
    describe: (world) => `runs ${JSON.stringify(world.runs.map((r) => ({ joinedOn: r.joinedOn, matched: r.matched })))}; differences ${world.differences.length}`,
  },
  {
    checkId: "matched-is-silent-mismatched-is-an-object",
    // 3. Three disbursements agree; two disagree on the net that landed.
    world: () => {
      const agree = [rec("PAY-40001", "1 Ash St", 2600, 213.2), rec("PAY-40002", "2 Ash St", 2200, 180.4), rec("PAY-40003", "3 Ash St", 1950, 159.9)];
      const sA = [...agree, rec("PAY-40004", "4 Ash St", 2400, 196.8, 2203.2), rec("PAY-40005", "5 Ash St", 2100, 172.2, 1627.8)];
      const sB = [...agree, rec("PAY-40004", "4 Ash St", 2400, 196.8, 2163.2), rec("PAY-40005", "5 Ash St", 2100, 172.2, 1927.8)];
      return new TwoRecordsWorld({ contract: contract({ threshold: { amount: 5000, mismatchRate: 1 } }), sourceA: sA, sourceB: sB });
    },
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const want = { "PAY-40004": [2203.2, 2163.2], "PAY-40005": [1627.8, 1927.8] };
      const ds = world.differences;
      const run = world.runs[0];
      return (
        world.runs.length === 1 &&
        run.matched === 3 &&
        run.mismatched === 2 &&
        ds.length === 2 &&
        ds.every((d) => {
          const w = want[d.key];
          // net: the bank (a) is master.
          return Array.isArray(w) && d.field === "net" && d.valueA === w[0] && d.valueB === w[1] && d.masterValue === w[0] && d.status === "open";
        }) &&
        new Set(ds.map((d) => d.key)).size === 2 &&
        writes(world).length === 0 &&
        world.changedFields().length === 0
      );
    },
    describe: (world) => `differences ${JSON.stringify(world.differences)}; writes ${writes(world).length}; changed ${world.changedFields().length}`,
  },
  {
    checkId: "nothing-is-auto-corrected",
    // 4. One open difference on fees. Run, a person accepts an hour later, run
    //    again, and a third run to prove the write is not repeated.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-50001", "9 Grevillea Pl, Cairns", 2800, 210, 2570.4), rec("PAY-50002", "11 Grevillea Pl, Cairns", 2300, 188.6)],
        sourceB: [rec("PAY-50001", "9 Grevillea Pl, Cairns", 2800, 229.6, 2570.4), rec("PAY-50002", "11 Grevillea Pl, Cairns", 2300, 188.6)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(HOUR);
      const d = world.differences.find((x) => x.key === "PAY-50001" && x.field === "fees");
      if (d && writes(world).length === 0) world.accept(d.id, ACCEPTOR);
      world.advance(HOUR);
      await build(world.ports());
      world.advance(HOUR);
      await build(world.ports());
    },
    holds: (world) => {
      const acc = world.acceptances;
      const ws = writes(world);
      if (acc.length !== 1 || ws.length !== 1) return false;
      const w = ws[0];
      const iWrite = world.calls.indexOf(w);
      const iPropose = world.firstCall("gate", (c) => c.request?.propose === acc[0].differenceId);
      return (
        iPropose >= 0 &&
        iPropose < iWrite &&
        Date.parse(w.at) >= Date.parse(acc[0].acceptedAt) &&
        w.request?.correction?.acceptedBy === ACCEPTOR &&
        w.request?.correction?.differenceId === acc[0].differenceId &&
        w.request?.source === "a" &&
        w.request?.field === "fees" &&
        w.request?.value === 229.6 &&
        w.response?.writtenId != null &&
        world.differences.filter((d) => d.key === "PAY-50001").length === 1
      );
    },
    describe: (world) => `writes ${JSON.stringify(writes(world).map((c) => ({ at: c.at, ...c.request })))}; acceptances ${JSON.stringify(world.acceptances)}`,
  },
  {
    checkId: "orphans-are-a-queue",
    // 5. A deposit with no statement line, and a statement line with no deposit.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-60001", "2 Jacaranda St", 2500, 205), rec("PAY-60007", "6 Jacaranda St", 1800, 147.6)],
        sourceB: [rec("PAY-60001", "2 Jacaranda St", 2500, 205), rec("PAY-60008", "8 Jacaranda St", 2050, 168.1)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const os = world.orphans;
      const oa = os.find((o) => o.key === "PAY-60007");
      const ob = os.find((o) => o.key === "PAY-60008");
      const handed = (o) => calls(world, "escalate").some((c) => c.request?.orphan === o.key && c.request?.owner === OWNER && c.request?.source === o.source);
      return (
        os.length === 2 &&
        !!oa &&
        !!ob &&
        oa.source === "a" &&
        ob.source === "b" &&
        [oa, ob].every((o) => typeof o.reason === "string" && o.reason.trim().length > 0 && o.owner === OWNER && handed(o)) &&
        world.runs.length === 1 &&
        world.runs[0].orphaned === 2 &&
        world.runs[0].matched === 1
      );
    },
    describe: (world) => `orphans ${JSON.stringify(world.orphans)}; runs ${JSON.stringify(world.runs.map((r) => r.orphaned))}`,
  },
  {
    checkId: "tolerance-is-written-down",
    // 6. Two cents on the net is inside the written tolerance. Two cents on the
    //    fees is not: fees carry no tolerance, so it is open.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-70001", "5 Bottlebrush Dr", 2600, 213.2, 2386.8), rec("PAY-70002", "7 Bottlebrush Dr", 2200, 180.4)],
        sourceB: [rec("PAY-70001", "5 Bottlebrush Dr", 2600, 213.2, 2386.79), rec("PAY-70002", "7 Bottlebrush Dr", 2200, 180.42, 2019.6)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const c = contract();
      const small = world.differences.find((d) => d.key === "PAY-70001");
      const large = world.differences.find((d) => d.key === "PAY-70002");
      const run = world.runs[0];
      return (
        world.differences.length === 2 &&
        !!small &&
        !!large &&
        small.field === "net" &&
        small.status === "within_tolerance" &&
        large.field === "fees" &&
        large.status === "open" &&
        world.differences.filter((d) => d.status === "within_tolerance").every((d) => Object.prototype.hasOwnProperty.call(c.toleranceByField, d.field)) &&
        world.runs.length === 1 &&
        run.withinTolerance === 1 &&
        run.mismatched === 1 &&
        run.matched === 0
      );
    },
    describe: (world) => `differences ${JSON.stringify(world.differences.map((d) => ({ key: d.key, field: d.field, status: d.status })))}`,
  },
  {
    checkId: "runs-on-a-schedule-and-publishes-regardless",
    // 7. Everything agrees, two scheduled mornings: two all-clears.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        ...pairOf(rec("PAY-80001", "1 Lilly Pilly Ct", 2600, 213.2), rec("PAY-80002", "3 Lilly Pilly Ct", 2350, 192.7), rec("PAY-80003", "5 Lilly Pilly Ct", 1900, 155.8)),
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(24 * HOUR);
      await build(world.ports());
    },
    holds: (world) => {
      const rs = world.runs;
      return (
        rs.length === 2 &&
        calls(world, "publish_report").length === 2 &&
        rs.every(
          (r) =>
            [r.matched, r.withinTolerance, r.mismatched, r.orphaned, r.corrected].every(isCount) &&
            r.matched === 3 &&
            r.withinTolerance === 0 &&
            r.mismatched === 0 &&
            r.orphaned === 0 &&
            r.corrected === 0 &&
            typeof r.publishedAt === "string" &&
            r.publishedAt.length > 0,
        ) &&
        rs[0].publishedAt !== rs[1].publishedAt &&
        world.differences.length === 0
      );
    },
    describe: (world) => `runs ${JSON.stringify(world.runs)}`,
  },
  {
    checkId: "thresholds-route-to-a-person",
    // 8. A $1,200 short-pay on one of two disbursements: over the $500 amount,
    //    and one of two is over the 40% rate.
    world: () =>
      new TwoRecordsWorld({
        contract: contract({ threshold: { amount: 500, mismatchRate: 0.4 } }),
        sourceA: [rec("PAY-90001", "14 Paperbark Way", 3200, 262.4, 1737.6), rec("PAY-90002", "16 Paperbark Way", 2400, 196.8)],
        sourceB: [rec("PAY-90001", "14 Paperbark Way", 3200, 262.4, 2937.6), rec("PAY-90002", "16 Paperbark Way", 2400, 196.8)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
    },
    holds: (world) => {
      const iPublish = world.firstCall("publish_report");
      const iNotify = world.firstCall("notify", (c) => c.request?.to === OWNER && String(c.request?.detail ?? "").includes("PAY-90001"));
      const iRate = world.firstCall("escalate", (c) => /rate/i.test(String(c.request?.reason ?? "")));
      return (
        world.runs.length === 1 &&
        iPublish >= 0 &&
        iNotify >= 0 &&
        iNotify < iPublish &&
        iRate >= 0 &&
        iRate < iPublish &&
        calls(world, "notify").every((c) => !String(c.request?.detail ?? "").includes("PAY-90002")) &&
        writes(world).length === 0
      );
    },
    describe: (world) => `notices ${JSON.stringify(world.notices)}; escalations ${JSON.stringify(world.escalations)}`,
  },
  {
    checkId: "history-survives-the-fix",
    // 9. The agency charged $229.60 in fees; the books coded $210. Accepted,
    //    written into the books, both originals kept.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-11001", "22 Melaleuca St", 2800, 210, 2570.4)],
        sourceB: [rec("PAY-11001", "22 Melaleuca St", 2800, 229.6, 2570.4)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(2 * HOUR);
      const d = world.differences.find((x) => x.key === "PAY-11001");
      if (d) world.accept(d.id, ACCEPTOR);
      world.advance(HOUR);
      await build(world.ports());
    },
    holds: (world) => {
      const d = world.differences.find((x) => x.key === "PAY-11001" && x.field === "fees");
      if (!d) return false;
      const c = world.correctionFor(d.id);
      const changed = world.changedFields();
      return (
        world.recordOf("a", "PAY-11001")?.fields.fees === 229.6 &&
        d.valueA === 210 &&
        d.valueB === 229.6 &&
        d.masterValue === 229.6 &&
        !!c &&
        c.acceptedBy === ACCEPTOR &&
        typeof c.acceptedAt === "string" &&
        typeof c.writtenId === "string" &&
        c.writtenId.length > 0 &&
        changed.length === 1 &&
        changed.every((f) =>
          world.corrections.some((k) => {
            const kd = world.differences.find((x) => x.id === k.differenceId);
            return kd && kd.key === f.key && kd.field === f.field && k.target === f.source && k.writtenId && k.acceptedBy;
          }),
        ) &&
        world.runs.length === 2 &&
        world.runs[1].corrected === 1
      );
    },
    describe: (world) => `differences ${JSON.stringify(world.differences)}; corrections ${JSON.stringify(world.corrections)}; changed ${JSON.stringify(world.changedFields())}`,
  },
  {
    checkId: "the-record-by-key",
    // 10. Rent mismatched in one run, accepted, written in the next; then read
    //     by the payment id.
    world: () =>
      new TwoRecordsWorld({
        contract: contract(),
        sourceA: [rec("PAY-12001", "8 Tuckeroo Ct", 2550, 209.1, 2390.9), rec("PAY-12002", "10 Tuckeroo Ct", 2100, 172.2)],
        sourceB: [rec("PAY-12001", "8 Tuckeroo Ct", 2600, 209.1, 2390.9), rec("PAY-12002", "10 Tuckeroo Ct", 2100, 172.2)],
      }),
    drive: async (build, world) => {
      await build(world.ports());
      world.advance(4 * HOUR);
      const d = world.differences.find((x) => x.key === "PAY-12001");
      if (d) world.accept(d.id, ACCEPTOR);
      world.advance(20 * HOUR);
      await build(world.ports());
    },
    holds: (world) => {
      const h = world.historyFor("PAY-12001");
      const firstRun = world.runs[0];
      const d = h.differences.find((x) => x.field === "rent");
      const c = d ? h.corrections.find((x) => x.differenceId === d.id) : undefined;
      return (
        world.runs.length === 2 &&
        !!firstRun &&
        h.runs.some((r) => r.id === firstRun.id) &&
        !!d &&
        d.valueA === 2550 &&
        d.valueB === 2600 &&
        d.masterValue === 2600 &&
        !!c &&
        c.acceptedBy === ACCEPTOR &&
        typeof c.writtenId === "string" &&
        world.historyFor("PAY-12002").differences.length === 0
      );
    },
    describe: (world) => `history ${JSON.stringify(world.historyFor("PAY-12001"))}`,
  },
  {
    checkId: "survives-the-builder",
    // 11. Not a runtime property. The runner reports it as evidence_required
    // and never scores it green here.
    world: () => new TwoRecordsWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];

// The pass test runs on the landlord's own books and the agency's real
// statements, by hand, with a person on the correction. A stub cannot pass it
// and is not asked to.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new TwoRecordsWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
